"use client"

import * as React from "react"
import { cn } from "cn"

import { Badge } from "@/components/standard/badge"

export type ToggleableBadgeItem = {
  id: string
  label: string
}

function ToggleableBadges({
  className,
  items,
  value,
  defaultValue,
  onValueChange,
}: {
  className?: string
  items: ToggleableBadgeItem[]
  value?: string
  defaultValue?: string
  onValueChange?: (id: string) => void
}) {
  const [uncontrolled, setUncontrolled] = React.useState(
    defaultValue ?? items[0]?.id
  )
  const selected = value ?? uncontrolled

  function select(id: string) {
    if (value === undefined) {
      setUncontrolled(id)
    }
    onValueChange?.(id)
  }

  return (
    <div
      data-slot="toggleable-badges"
      className={cn("flex flex-wrap gap-1.5", className)}
    >
      {items.map((item) => {
        const isOn = item.id === selected
        const tone = isOn ? "default" : "outline"

        return (
          <button
            key={item.id}
            type="button"
            aria-pressed={isOn}
            onClick={() => select(item.id)}
            className="rounded-full"
          >
            <Badge tone={tone}>{item.label}</Badge>
          </button>
        )
      })}
    </div>
  )
}

export { ToggleableBadges }
